package com.nullo.voidapp.core.model

import androidx.compose.runtime.Immutable

/** Represents a message in a conversation. */
@Immutable
sealed class Message(open val id: Long) {

    /** A message sent by the user to the AI. */
    data class Prompt(
        override val id: Long,
        val query: String,
        val images: List<ImageAttachment> = emptyList(),
        val createdAt: Long? = null,
    ) : Message(id)

    /** A text response generated by the AI, optionally including reasoning. */
    data class Completion(
        override val id: Long,
        val text: String,
        val reasoning: String? = null,
        val isStreaming: Boolean = false,
        val modelId: String? = null,
        val createdAt: Long? = null,
    ) : Message(id)

    /** An AI response containing generated images. */
    data class Images(
        override val id: Long,
        val images: List<ImageAttachment>,
        val modelId: String? = null,
        val createdAt: Long? = null,
    ) : Message(id)

    /** Represents an error returned while processing a request. */
    data class Error(
        override val id: Long,
        val reason: ErrorReason,
        val rawMessage: String?,
    ) : Message(id)

    /**
     * Indicates that an AI response was interrupted before completion.
     * @param text Text generated before interruption, or `null` if none was generated.
     */
    data class Interrupted(
        override val id: Long,
        val text: String?,
    ) : Message(id)

    /** Indicates that images are currently being generated. */
    data class ImageLoading(override val id: Long) : Message(id)
}

/** Represents an image stored in the app storage: attached to a prompt or generated by the AI. */
@Immutable
data class ImageAttachment(
    val relativePath: String,
    val mimeType: String,
)

/** Represents a type of error returned while processing a request. */
enum class ErrorReason {
    NETWORK,
    SERVER_INTERNAL,
    REQUEST_REJECTED,
    INSUFFICIENT_CREDITS,
    RATE_LIMITED,
    UNAUTHORIZED,
    UNEXPECTED,
    ;

    companion object {

        fun fromKey(key: String?) = entries
            .firstOrNull { it.name == key }
            ?: UNEXPECTED
    }
}
